export type Input = void;

export type Output = u64;

export default function (in: Input): Output {
  const values = [1, 2, 3, ...[]];

  return values.length;
}

export type Input = void;

export type Output = u64;

export default function (in: Input): Output {
  const source: u64[] = [3, 4, 5];

  const values = [1, 2, ...target = source];

  return values.length;
}

export type Input = void;

export type Output = u64;

export default function (in: Input): Output {
  const values = [5, ...[6, 7, 8], 9];

  return values.length;
}

